GimCorpus.put(406,0,[[1,4,"וכל שאין בהן וכו'. כתב הראב\"ד ז\"ל זהו להחם כו' בירו' לא תאסור ולא תשרי עכ\"ל:",1,0],[1,5,"כל מלאכה שאפשר וכו'. כתב הראב\"ד ז\"ל אין לזה טעם אלא מפני שהוא מכוין מלאכתו ביו\"ט ומרבה הטורח ליום קדש עכ\"ל:",1,0],[1,6,"ולמה לא אסרוה וכו'. כתב הראב\"ד ז\"ל לא אמרו זה אלא כנגד ומשלוח מנות ומשלוח כלים איש לרעהו שהן מותרין ביו\"ט וכל אלה אינן צריכין לזה הטעם אלא מפני שהוא כבוד היום יותר מאמש עכ\"ל:",1,0],[1,8,"ואופין ושוחטין וכו'. א\"א בכל אלה אין טעם למה אין תולשין ירק ואין מלקטין פירות ביו\"ט מן האילן שהרי בני יומן יפין יותר. והירושלמי סומך אותו על אך אשר יאכל לכל נפש הוא לבדו יעשה לכם וסמיך ליה ושמרתם את המצות שהיא מלאכה בתלוש עכ\"ל:",1,0],[1,14,"בני החיל וכו'. כתב הראב\"ד ז\"ל יפה אמר אע\"פ שלא הסכים לדעת הרב ז\"ל:",1,0],[1,17,"ויש ביו\"ט מה שאין וכו'. כתב הראב\"ד ז\"ל לא הכל שוין בזה עכ\"ל:",1,0],[2,3,"וכן בהמת קדשים וכו'. כתב הראב\"ד ז\"ל ואפילו נולד בו מום מעיו\"ט אין רואין אותו לכתחילה ביו\"ט עכ\"ל:",1,0],[2,4,"בכור שנולד וכו'. כתב הראב\"ד ז\"ל ולמה אין רואין אותו לכתחלה שמא לא יהיה מום קבוע ונמצא מטלטל מה שאינו ראוי לו שאי אפשר בלא טלטול או שמא לא ידקדק בראייתו מפני שמחת יו\"ט עכ\"ל:",1,0],[2,7,"דגים שבביברים וכו'. כתב הראב\"ד ז\"ל זה אינו נכון שהרי חיה ועוף שהתירו אינו אלא ביברים קטנים ואפילו הכי דגים אין צדים והטעם מפני שהם מכוסין מן העין עכ\"ל:",1,0],[2,12,"כיוצא בו אגוזים ושקדים כו' ויש נוסחאות כו'. כתב הראב\"ד ז\"ל מעולם לא שמענו זאת הנוסחא:",1,0],[2,14,"ומביאין מן וכו'. כתב הראב\"ד ז\"ל ואיכא למימר דסמוך לעיר נמי בלא פותחת מוכן הוא אבל לסוף התחום שהוא רחוק בעי ר' יוסי פותחת עכ\"ל:",1,0],[3,8,"והלש עיסה מערב יו\"ט וכו'. כתב הראב\"ד ז\"ל ואנו מחלקין בין עיסת הארץ לעיסת ח\"ל דעיסת ח\"ל כיון דקי\"ל כשמואל דאמר אוכל והולך ואחר כך מפריש אין כאן משום מתקן טבלים ביו\"ט דהלכה כרבא דהוא בתרא דפליג אדאבוה דשמואל:",1,0],[3,10,"אבל לגבל וכו'. כתב הראב\"ד ז\"ל כבר כתבנו בהלכות שבת שכל זה שבוש עכ\"ל:",1,0],[3,13,"אין כותשין את הריפות וכו'. כתב הראב\"ד ז\"ל אין הדעת נוחה מזה הטעם אבל אנשי בבל עיקר תבשיליהן דייסא שאוכלין בו הלחם והיו עושין אותה במדוכה מכתשת גדולה ומכתשת קטנה הרי היא להם שינוי גדול אבל אנשי ארץ ישראל די להם כל הימים בקטנה ואין בה שינוי עכ\"ל:",1,0],[3,14,"הקמח אע\"פ שרקדו וכו'. כתב הראב\"ד ז\"ל אני אומר שהלכה כרבי יהודה ורב פפיאס שאמרו שונין ואם נפל בו צרור או קיסם אסור ואם שינה מותר עכ\"ל:",1,0],[4,1,"אין מוציאין את האש וכו'. כתב הראב\"ד ז\"ל ויאמר מפני שהוא מוליד ואין כאן הכנה והוא הטעם שמפרש בגמרא עכ\"ל:",1,0],[4,3,"אבל נופץ את ראשה וכו'. כתב הראב\"ד ז\"ל ואפילו במחט שהרי אמרו מוחטין עכ\"ל:",1,0],[4,10,"אין מבקעין וכו'. כתב הראב\"ד ז\"ל איני יודע לאיזה דבר נלמוד מזה הטעם והטעם השוה לכל הדברים להלכה קי\"ל כר' יהודה דמכשירין שא\"א לעשותן מעיו\"ט מותר לעשותן כדרכן ביו\"ט והוא שיהיה דבר הצריך ולא יהא בו תקון לחול ואם אפשר לעשותן מעיו\"ט עושין אותן ע\"י שינוי וזהו טעם לביקוע וטעם למלח. ועם כל זה צריך הדבר תקון שהרי לדעת חכמים אע\"פ שא\"א לעשותן מעיו\"ט א\"כ תבלין מה טעם נדוכין כדרכן ומלח למה אפילו בשינוי אלא לא מסרן הכתוב אלא לחכמים והם אמרו יש מכשירין שהם כאוכל עצמו והם התבלין והמלח שנכנסים באוכל עצמו והתירו זה כדרכו וזה על ידי שינוי ואפילו לדעת חכמים וכן לר' יהודה מפני שמספיק למלח בהטייה לדוכן כל צרכה. ואפשר דבקוע עצים מפני שא\"א לאפות ולבשל בלא עצים עשו אותו כדיכת המלח והתירו אותו על ידי שינוי עכ\"ל:",1,0],[4,20,"ואין מטילין חלשים וכו'. כ' הראב\"ד ז\"ל בגמרא מפרש מטילין חלשים על קדשים של יו\"ט ביו\"ט אבל לא על המנות של חול ביו\"ט ואפילו בקדשים ועם בניו ובני ביתו מותר ואפילו מנה גדולה כנגד מנה קטנה עכ\"ל:",1,0],[5,4,"אין מוליכין את הסולם וכו'. כתב הראב\"ד ז\"ל הוא אמר דבר זה אבל הגמרא לא אמרה כן ולא חלקה בדבר אלא העמידה כתנאי ורב חנן בר אמי כתנא קמא דמפליג בין רה\"ר לרה\"י ורב אמר כרבי אליעזר ור\"ש דלא מפליג וב\"ה דשרו בתרוייהו שרו עכ\"ל:",1,0],[5,10,"חפצי הפקר וכו'. כתב הראב\"ד ז\"ל טעה במשנתנו ושל עולי בבל כרגלי הממלא וכבר נפקא לן מהלכתא דבמסכת עירובין אוקימנא כרבנן דפליגי על רבי יוחנן בן נורי דחפצי הפקר קונים שביתה ויש להם אלפים אמה לכל רוח וממקום שביתתו בין השמשות ומזה הטעם לא הביא הרב ז\"ל בהלכותיו מחלוקת דרב נחמן ורב ששת שחלקו במילא ונתן לחבירו דלאו אליבא דהלכתא פליגי בבור של עולי בבל אבל יש לנו עליו טענה שהרי מחלוקתם עומדת במעינות הנובעים עכ\"ל:",1,0],[5,14,"בור של יחיד וכו'. כתב הראב\"ד ז\"ל זה שבוש כמו שכתבתי למעלה עכ\"ל:",1,0],[5,15,"שור של רועה וכו'. כתב הראב\"ד ז\"ל זה שבוש אלא מפני שהוא זוכה לכל אחד ואחד בחלקו מעיו\"ט ואע\"פ שאין לו לשואל ברירה ה\"מ בדבר של שותפין שהם מקפידים בחלוקתם אבל הפטם זה שמוכר אותו אין עליו זאת ההקפדה כדי שיבא כל אדם ויקנה ויוליך לרגלו עכ\"ל:",1,0],[6,2,"ולמה נקרא שמו עירוב וכו'. כתב הראב\"ד ז\"ל הטעם הזה לנערים כי הוא שאול מערובי חצירות כלומר זה משום היכר הוא וזה משום היכר הוא מה זה שמו עירוב אף זה שמו עירוב ואינו כן אלא שהוא מערב צרכי שבת עם צרכי יו\"ט לעשותם יחד עכ\"ל:",1,0],[6,3,"עירובי תבשילין שיעורו וכו' ביום טוב בלבד. כתב הראב\"ד ז\"ל נ\"ל שאם אפה [ולא בישל או בישל ולא אפה] ונאכל העירוב או אבד מה שעשה בעוד שהעירוב קיים מותר לו לשבת עכ\"ל:",1,0],[6,14,"כל הדברים האלו וכו'. כתב הראב\"ד ז\"ל אע\"פ שיש בדבריו כעין טעם לא ראינו הגאונים הראשונים שחלקו בדבר זה וכל שכן הוא שהרי השני עתה חול גמור הוא שהרי אדר ואייר ואלול חסרים הם ואינן אלא יום אחד ראשי חדשים הסמוכין להם ואם יאמר בשני אם אתמול קדש והיום חול אין בדברי של אתמול כלום והיום תהיה זו תרומה על זו כל שכן שיכול לומר מאתמול עכ\"ל:",1,0],[6,22,"ימים שבין ראשון וכו'. כתב הראב\"ד ז\"ל ויום שמועה כבפניו דמי עכ\"ל:",1,0],[7,3,"הופך אדם את זיתיו וכו'. כתב הראב\"ד ז\"ל אני לא מצאתי כן אלא זיתיו הפוכין ושטין אבל בהפוך אחר לא שאינן מתעפשות כ\"כ והכי איתא בירושלמי עכ\"ל:",1,0],[7,8,"מטילים שכר במועד וכו'. כתב הראב\"ד ז\"ל הא דלא כהלכתא דר' יוסי ברבי יהודה דאמר הכי ופליגי רבנן עליה אבל בודאי אם החדש טוב לו מן הישן שלא מדרך הערמה מותר עכ\"ל:",1,0],[7,10,"עושין כל צרכי רבים וכו'. כתב הראב\"ד ז\"ל שהרבים צריכין להם אבל של יחיד וצריך להם חוטטין ולא חופרין עכ\"ל:",1,0],[7,12,"מי שרצה ללוות וכו'. כתב הראב\"ד ז\"ל לא כי אלא כדבר האבוד הם עכ\"ל:",1,0],[7,14,"ומותר לכתוב אגרות וכו'. כתב הראב\"ד ז\"ל שאילת שלום שמא לא יזדמן לו מוליך הכתב. מחשב יציאותיו צורך המועד הוא עכ\"ל:",1,0],[8,3,"ומרביצין את השדה במועד וכו'. כתב הראב\"ד ז\"ל משנת ראב\"י אני רואה בכאן דראב\"י הוא דאמר שלא ישקה כל השדה והוא אמר נמי זרעים דלא שתו קודם המועד לא ישקה אותם במועד וחכמים מתירין בזה ובזה בין באילן בין בזרעים והכי איתא בירושלמי. וזה המחבר תופס דברי ראב\"י ולא ידעתי מי עשאו מכריע על דברי חכמים ואם יאמר רב יהודה הכריע דמפרש לדעת ראב\"י הלא רבא למד יותר מדברי חכמים. ואם יאמר הלא הקשו על רבא מגריד ועמדה הקושיא לפי שלא נחלקו בגריד ודמו התרביצא לשדה גריד שהוא אסור להשקותו א\"כ למה אמר שמרביצין את השדה במועד. וסוף דבר כל הדברים צריכין תקון גדול עכ\"ל:",1,0],[8,4,"זרעים שלא שתו וכו'. כתב הראב\"ד הברייתא שונה את זה על זרעים שלא שתו לפני המועד והוא שונה אותו על כל שדה של אילנות ואולי מדעתו למד זה:",1,0],[8,4,"ועושין נברכת וכו'. כתב הראב\"ד ז\"ל לא נמלט מן הטעות שטועין בו רבים שהם סוברים נברכת כמו עוגיאות וטעו טעיות גדולות הידועות לכל מבין וכי אינה אלא ענין חפירת הקבר וכן אמרו בירושלמי נברכת זו הבקיע וכן כל שהוא בה חפירה נקרא בקיע והוא החפירה שאנו עושין עכשיו למת והם היו עושין אותם קודם לקבר עד שיחפרו לו כוך או בנין נאה ואותו הבקיע עושין במועד עד לאחר שיעשה לו כוך או קבר לפי כבודו עכ\"ל:",2,0],[8,8,"ואין בונין וכו'. כתב הראב\"ד גם זה טעות וקודם שימות המת למה מתקנין אותו כלל אלא הכל משימות המת, עכ\"ל:",1,0],[8,16,"אין מפנין וכו'. כתב הראב\"ד ז\"ל בירושלמי משל אחרים בתוך שלו אפילו מנאה לכעורה שמחה היא לאדם שהוא דר בתוך שלו. ונ\"ל אפילו מחצר אחרת ואע\"פ שיש לדקדק על זה הירושלמי מן הגמרא נאה ומתקבל הוא, עכ\"ל:",1,0],[8,19,"ואפילו מקום שנהגו וכו'. כתב הראב\"ד ז\"ל לא כן צורת ההלכה אלא לר' מאיר כל מלאכה שהיא לצורך המועד גומרה בי\"ד אפילו שלא נהגו לעשות ושלא לצורך המועד עושין במקום שנהגו לעשות ואתו רבנן למימר דהני ג' אומניות אתחולי נמי מתחילין אפילו במקום שנהגו שלא לעשות ולהתיר באלו ולא לאסור מדלא קאמר וחכמים אומרים אין עושין אלא שלש אומניות וכו' וכן מפורש בתוספתא וכן הרב ז\"ל והוא עיקר:",1,0]]);
